"""Supply meeting guidance and a counting Skill; delegate native tool selection."""

from pydantic import JsonValue

from experimental.curator.harness.preparation import PreparationRequest
from experimental.curator.harness.resources import (
    CapabilityContribution,
    CapabilityRegistrar,
    CapabilitySelection,
    RegistrationReceipt,
    SelectionRequest,
    SkillContribution,
    SkillSelection,
)
from experimental.curator.harness.state import Task
from experimental.curator.harness.strategies import CapabilityStrategy


SKILL_NAME = "meeting-workday-counting"
SKILL_SOURCE = "curator-capability"
CASE_ROUTE = "计算前先对照下方‘工作日计数：先判资格’案例：从本场规则确定起算位置与允许计数的日历类型"
MISSING_CASE_ROUTE = "工作日计数案例当前未能加载，不能声称已对照；仍须先从本场规则确定起算位置与允许计数的日历类型"

MEETING_GUIDANCE = f"""处理会议待办时，先确认本次会议名称、召开日期及对应材料。读取本次工作规则、会议记录、参会人名单和公司日历；当前上下文已完整取得的本次材料直接使用，只补读缺失、截断或更新部分。
事项取舍、人员、期限解释、拆分合并及输出形式均服从本次规则，不沿用其他会议的业务规则。
遇到‘N 个工作日内’，{CASE_ROUTE}，再按公司日历逐日取第 N 个合格日期。‘调休上班’是否计入只能由本场规则决定，不能凭‘上班’二字判断。交付前同时核对类型资格和计数序号，再按本场格式写日期及需要的星期；不要只检查截止日是不是工作日。案例正文已随输入提供时无需再读取；不为本次整理读取无关 Skill。
回复前对照本次材料核对事项、人员与日期。读取失败或依据不足时说明具体缺口，不补造事实，按本次规则交付有依据的部分和需确认事项，不用进度或计划替代结果。没有实际会议材料不虚构待办。只在回复中按本次规则交付，不交付文件，不附案例、计数表或内部核验说明。"""


class MeetingCapability(CapabilityStrategy):
    """Prepare one method Skill and select its body from actual runtime views."""

    def __init__(self, registrar: CapabilityRegistrar) -> None:
        self._registrar = registrar

    def _prepare_skills(self, request: PreparationRequest) -> tuple[SkillContribution, ...]:
        """Consume the complete asset; missing input remains a preparation error."""
        return (
            SkillContribution(
                name=SKILL_NAME,
                owner="capability",
                package=None,
                files={"SKILL.md": request.assets["meeting_workday_counting/SKILL.md"]},
                source="meeting-workday-counting-method",
            ),
        )

    def register(self, contribution: CapabilityContribution) -> RegistrationReceipt:
        """Preserve the host registrar's receipts and visible failures."""
        return self._registrar.register(contribution)

    async def select(self, request: SelectionRequest) -> CapabilitySelection:
        """Select only available identities; never interpret meeting data in code."""
        identities = [(skill.source, skill.name) for skill in request.skills]
        target = [
            skill for skill in request.skills
            if (skill.source, skill.name) == (SKILL_SOURCE, SKILL_NAME)
        ]
        if len(identities) != len(set(identities)):
            reason = "Skill 目录身份重复，无法安全选择案例正文。"
        elif not target:
            reason = "Skill 目录缺少工作日计数案例。"
        elif not target[0].available:
            reason = "工作日计数案例在当前目录中不可用。"
        else:
            return CapabilitySelection(
                tools=None,
                skills=tuple(
                    SkillSelection(
                        name=skill.name,
                        source=skill.source,
                        delivery="body"
                        if (skill.source, skill.name) == (SKILL_SOURCE, SKILL_NAME)
                        else "catalog",
                    )
                    for skill in request.skills if skill.available
                ),
                guidance=MEETING_GUIDANCE,
            )
        return CapabilitySelection(
            tools=None,
            skills=None,
            guidance=reason + "\n" + MEETING_GUIDANCE.replace(CASE_ROUTE, MISSING_CASE_ROUTE),
        )


def create(
    state: dict[str, JsonValue],
    task: Task,
    *,
    registrar: CapabilityRegistrar,
) -> MeetingCapability:
    """Bind an inert dependency without resetting task or session progress."""
    return MeetingCapability(registrar)
